def magic_square_test(matrix):
    n = len(matrix)
    target = sum(matrix[0])  # calculate the target sum of each row

    # check rows
    for row in matrix:
        if sum(row) != target:
            return False

    # check columns
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target:
            return False

    # check diagonals
    diagonal1 = sum(matrix[i][i] for i in range(n))
    diagonal2 = sum(matrix[i][n-i-1] for i in range(n))
    if diagonal1 != target or diagonal2 != target:
        return False

